class Student:
    def __init__(self, name):
        self.name = name
        self._marks = []

    def add_mark(self, mark):
        self._marks.append(mark)

    @property
    def average(self):
        return sum(self._marks) / len(self._marks) if self._marks else 0

    @property
    def grade(self):
        avg = self.average
        if avg >= 80:
            return 'A'
        elif avg >= 60:
            return 'B'
        return 'C'
